targets.expr:
max by(nodename) ((100 *
sum by (instance) (
  rate(node_cpu_seconds_total{
    job="node-exporter",
    mode=~"user|system"
  }[$__rate_interval])
)
/ on (instance) group_left
count by (instance) (count by (cpu, instance) (
  node_cpu_seconds_total{job="node-exporter"}
))
) * on(instance) group_left(nodename) node_uname_info{nodename=~"${server:regex}"})
